//! End-to-end tests of the `forhunt` binary against the synthetic fixtures
//! (`fixtures/synthetic`, generated by `tools/evtx-gen`).

use std::path::PathBuf;
use std::process::{Command, Output, Stdio};

use serde_json::Value;

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/synthetic")
}

fn fx(name: &str) -> String {
    fixtures().join(name).display().to_string()
}

fn forhunt(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_forhunt"))
        .args(args)
        .output()
        .expect("run forhunt")
}

fn ok(args: &[&str]) -> String {
    let o = forhunt(args);
    assert!(
        o.status.success(),
        "forhunt {args:?} failed: {}",
        String::from_utf8_lossy(&o.stderr)
    );
    String::from_utf8(o.stdout).expect("utf-8 output")
}

fn lines(s: &str) -> Vec<Value> {
    s.lines()
        .map(|l| serde_json::from_str(l).unwrap_or_else(|e| panic!("bad JSON line {l}: {e}")))
        .collect()
}

fn summary(v: &[Value]) -> &Value {
    let last = v.last().expect("output");
    &last["summary"]
}

#[test]
fn parse_counts_and_is_deterministic_across_threads() {
    let a = ok(&[
        "parse",
        "-q",
        "-t",
        "1",
        &fx("Security.evtx"),
        &fx("Sysmon.evtx"),
    ]);
    let b = ok(&[
        "parse",
        "-q",
        "-t",
        "4",
        &fx("Security.evtx"),
        &fx("Sysmon.evtx"),
    ]);
    let c = ok(&[
        "parse",
        "-q",
        "-t",
        "3",
        &fx("Sysmon.evtx"),
        &fx("Security.evtx"),
    ]);
    assert_eq!(a, b, "output must not depend on --threads");
    assert_eq!(a, c, "output must not depend on argument order");
    let v = lines(&a);
    assert_eq!(v.len(), 2548 + 608);
    for e in &v {
        assert!(e["id"].as_str().unwrap().contains(':'));
        assert!(e["timestamp"].as_str().unwrap().ends_with('Z'));
    }
}

#[test]
fn search_scenario_brute_force() {
    let out = ok(&[
        "search",
        "-q",
        &fx("Security.evtx"),
        "--event-id",
        "4625",
        "--field",
        "IpAddress=203.0.113.50",
        "--field",
        "TargetUserName=ADMINISTRATOR",
    ]);
    let v = lines(&out);
    let s = summary(&v);
    assert_eq!(s["matches"], 25);
    assert_eq!(s["shown"], 25);
    assert_eq!(s["truncated"], false);
    let e = &v[0];
    assert_eq!(e["eid"], 4625);
    assert_eq!(e["ch"], "Sec");
    assert_eq!(e["d"]["lt"], 10);
    assert_eq!(e["d"]["ip"], "203.0.113.50");
    // Hex-aware comparison: 0xC000006A written as 0xc000006a.
    let out = ok(&[
        "search",
        "-q",
        &fx("Security.evtx"),
        "-e",
        "4625",
        "-f",
        "SubStatus=0xC000006A",
    ]);
    assert_eq!(summary(&lines(&out))["matches"], 35);
}

#[test]
fn search_cap_summary_and_suggestions() {
    let out = ok(&["search", "-q", &fx("Security.evtx"), "-n", "5"]);
    let v = lines(&out);
    assert_eq!(v.len(), 6);
    let s = summary(&v);
    assert_eq!(s["shown"], 5);
    assert_eq!(s["matches"], 2548);
    assert_eq!(s["truncated"], true);
    let narrow = s["narrow"].as_array().unwrap();
    assert!(!narrow.is_empty());
    assert!(
        narrow
            .iter()
            .all(|n| n["add"].as_str().unwrap().starts_with("--"))
    );
}

