#[test]
fn stats_reports_coverage_and_tampering() {
    let out = ok(&["stats", "-q", &fx("Security.evtx"), &fx("System.evtx")]);
    let v = lines(&out);
    let head = &v[0]["stats"];
    assert_eq!(head["events"], 2548 + 302);
    let present = v.iter().find(|l| l.get("present").is_some()).unwrap();
    assert_eq!(present["present"]["Sec"]["4625"], 37);
    assert_eq!(present["present"]["Sys"]["7045"], 1);
    let tamper = v.iter().find(|l| l.get("log_tampering").is_some()).unwrap();
    assert_eq!(tamper["log_tampering"][0]["eid"], 1102);
    assert_eq!(tamper["log_tampering"][0]["user"], "administrator");
    let json: Value =
        serde_json::from_str(&ok(&["stats", "-q", "-F", "json", &fx("Security.evtx")])).unwrap();
    assert_eq!(json["events"], 2548);
    let csv = ok(&["stats", "-q", "-F", "csv", &fx("Security.evtx")]);
    assert!(csv.starts_with("section,key,detail,count\n"));
}

#[test]
fn show_round_trip() {
    let out = ok(&["search", "-q", &fx("Security.evtx"), "-e", "1102"]);
    let id = lines(&out)[0]["id"].as_str().unwrap().to_string();
    let dir = fixtures().display().to_string();
    let j: Value = serde_json::from_str(&ok(&["show", "-q", &id, "-p", &dir])).unwrap();
    assert_eq!(j["event_id"], 1102);
    assert_eq!(j["data"]["SubjectUserName"], "administrator");
    let xml = ok(&["show", "-q", &id, "-p", &dir, "-F", "xml"]);
    assert!(xml.contains("<EventID>1102</EventID>"), "{xml}");
    let o = forhunt(&["show", "-q", "00000000:1", "-p", &dir]);
    assert_eq!(o.status.code(), Some(1));
    let o = forhunt(&["show", "-q", "not-an-id", "-p", &dir]);
    assert_eq!(o.status.code(), Some(1));
}

#[test]
fn ids_differ_for_same_file_name_on_two_hosts() {
    let a = lines(&ok(&["parse", "-q", &fx("Security.evtx")]));
    let b = lines(&ok(&["parse", "-q", &fx("dc01/Security.evtx")]));
    let ka = a[0]["id"]
        .as_str()
        .unwrap()
        .split(':')
        .next()
        .unwrap()
        .to_string();
    let kb = b[0]["id"]
        .as_str()
        .unwrap()
        .split(':')
        .next()
        .unwrap()
        .to_string();
    assert_ne!(ka, kb);
}

#[test]
fn corrupt_and_truncated_inputs() {
    let o = forhunt(&["parse", &fx("corrupt.evtx"), "-o", "-"]);
    assert!(o.status.success());
    let err = String::from_utf8_lossy(&o.stderr);
    assert!(err.contains("bad chunks"), "{err}");
    assert!(lines(&String::from_utf8_lossy(&o.stdout)).len() > 2000);
    let o = forhunt(&["parse", "-q", "--strict", &fx("corrupt.evtx")]);
    assert_eq!(o.status.code(), Some(4));

    let o = forhunt(&["parse", &fx("truncated.evtx")]);
    assert!(o.status.success());
    let v = lines(&String::from_utf8_lossy(&o.stdout));
    assert_eq!(v.len(), 216);
    assert!(String::from_utf8_lossy(&o.stderr).contains("truncated"));

    let o = forhunt(&["parse", "-q", &fx("empty.evtx"), &fx("not-evtx.evtx")]);
    assert_eq!(o.status.code(), Some(3));
    let o = forhunt(&["parse", "-q", "/nonexistent/path"]);
    assert_eq!(o.status.code(), Some(3));
    // Bad input mixed with good input: good input is still processed.
    let o = forhunt(&["stats", "-q", &fx("empty.evtx"), &fx("System.evtx")]);
    assert!(o.status.success());
}

#[test]
fn csv_output() {
    let out = ok(&[
        "search",
        "-q",
        &fx("System.evtx"),
        "-e",
        "7045",
        "-F",
        "csv",
    ]);
    let mut l = out.lines();
    assert!(
        l.next()
            .unwrap()
            .starts_with("RecordNumber,EventRecordId,TimeCreated,EventId,Level,Provider")
    );
    let row = l.next().unwrap();
    assert!(row.contains("PSEXESVC"), "{row}");
    assert!(row.contains(",7045,"), "{row}");
    assert!(row.contains("System.evtx"), "{row}");
    assert!(l.next().is_none());
}

fn dir_files(d: &std::path::Path) -> Vec<String> {
    let mut v: Vec<String> = std::fs::read_dir(d)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    v.sort();
    v
}

#[test]
fn folder_input_concatenates_and_filters_by_host() {
    let all = ok(&["parse", "-q", &fx(""), "-F", "csv"]);
    // One header, rows from both hosts.
    assert_eq!(all.matches("RecordNumber,").count(), 1);
    assert!(all.contains("WS-07"));
    assert!(all.to_lowercase().contains("dc01"));
    let dc = ok(&["parse", "-q", &fx(""), "-F", "csv", "--computer", "dc01"]);
    let rows: Vec<&str> = dc.lines().skip(1).collect();
    assert!(!rows.is_empty());
    assert!(rows.iter().all(|r| !r.contains("WS-07")), "{dc}");
}

#[test]
fn split_output_per_file_and_per_host() {
    let d = tempfile::tempdir().unwrap();
    let out = d.path().join("by-file");
    ok(&[
        "parse",
        "-q",
        &fx(""),
        "-F",
        "csv",
        "-O",
        out.to_str().unwrap(),
        "--split",
        "file",
    ]);
    let files = dir_files(&out);
    assert!(files.contains(&"Security.csv".to_string()), "{files:?}");
    assert!(
        files.contains(&"dc01__Security.csv".to_string()),
        "{files:?}"
    );
    for f in &files {
        let s = std::fs::read_to_string(out.join(f)).unwrap();
        assert!(s.starts_with("RecordNumber,"), "{f}");
        assert_eq!(s.matches("RecordNumber,").count(), 1, "{f}");
    }

    let out = d.path().join("by-host");
    ok(&[
        "parse",
        "-q",
        &fx(""),
        "-F",
        "jsonl",
        "-O",
        out.to_str().unwrap(),
        "--split",
        "host",
    ]);
    let files = dir_files(&out);
    assert!(files.len() >= 2, "{files:?}");
    assert!(files.iter().all(|f| f.ends_with(".jsonl")), "{files:?}");
    for f in &files {
        let s = std::fs::read_to_string(out.join(f)).unwrap();
        let hosts: std::collections::BTreeSet<String> = lines(&s)
            .iter()
            .map(|v| v["computer"].as_str().unwrap_or("").to_lowercase())
            .collect();
        assert_eq!(hosts.len(), 1, "{f}: {hosts:?}");
    }
}

#[test]
fn hayabusa_normalisation() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("hb.jsonl");
    let sec = fx("Security.evtx");
    let rec = lines(&ok(&["search", "-q", &sec, "-e", "1102", "-F", "jsonl"]))[0]["record_id"]
        .as_u64()
        .unwrap();
    let hb = format!(
        "{{\"Timestamp\":\"2024-03-11 19:30:00.000 +09:00\",\"RuleTitle\":\"Log Cleared\",\"Level\":\"high\",\"Computer\":\"WS-07.contoso.local\",\"Channel\":\"Sec\",\"EventID\":1102,\"RecordID\":{rec},\"Details\":{{\"User\":\"administrator\"}},\"MitreTactics\":[\"Evas\"],\"MitreTags\":[\"T1070.001\"],\"EvtxFile\":{}}}\n\
         {{\"Timestamp\":\"2024-03-11T10:00:00Z\",\"RuleTitle\":\"Noise\",\"Level\":\"info\",\"Computer\":\"WS-07\",\"Channel\":\"Sec\",\"EventID\":4624,\"RecordID\":1,\"Details\":\"-\"}}\n",
        serde_json::to_string(&sec).unwrap()
    );
    std::fs::write(&p, hb).unwrap();
    let v = lines(&ok(&["hayabusa", "-q", &p.display().to_string()]));
    assert_eq!(v.len(), 2);
    assert_eq!(v[0]["t"], "2024-03-11T10:30:00.000000Z");
    assert_eq!(v[0]["lvl"], "high");
    let id = v[0]["id"].as_str().unwrap().to_string();
    let shown: Value = serde_json::from_str(&ok(&["show", "-q", &id, "-p", &sec])).unwrap();
    assert_eq!(shown["event_id"], 1102);
    assert_eq!(v[1]["summary"]["below_min_level"], 1);
}

#[test]
fn hayabusa_windows_paths_resolve_by_suffix() {
    // Hayabusa run on Windows: backslash paths that do not exist here. Two
    // inputs are named Security.evtx; the parent folder disambiguates.
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("hb.jsonl");
    let dc = fx("dc01/Security.evtx");
    let rec = lines(&ok(&["search", "-q", &dc, "-F", "jsonl", "-n", "1"]))[0]["record_id"]
        .as_u64()
        .unwrap();
    let line = |f: &str| {
        format!(
            "{{\"Timestamp\":\"2024-03-11T08:00:00Z\",\"RuleTitle\":\"R\",\"Level\":\"high\",\"Computer\":\"DC01\",\"Channel\":\"Sec\",\"EventID\":4634,\"RecordID\":{rec},\"Details\":\"-\",\"EvtxFile\":{}}}\n",
            serde_json::to_string(f).unwrap()
        )
    };
    let hb = line("C:\\cases\\x\\dc01\\Security.evtx") + &line("C:\\cases\\Security.evtx");
    std::fs::write(&p, hb).unwrap();
    let v = lines(&ok(&[
        "hayabusa",
        "-q",
        &p.display().to_string(),
        "-p",
        &fx(""),
    ]));
    let dc_key = lines(&ok(&["search", "-q", &dc, "-F", "jsonl", "-n", "1"]))[0]["id"]
        .as_str()
        .unwrap()
        .to_string();
    assert_eq!(v[0]["id"], dc_key.as_str());
    // `cases\Security.evtx` matches both inputs equally: no id rather than a wrong one.
    assert!(v[1].get("id").is_none() || v[1]["id"].is_null(), "{}", v[1]);
}

#[test]
fn broken_pipe_is_not_an_error() {
    let mut child = Command::new(env!("CARGO_BIN_EXE_forhunt"))
        .args(["parse", "-q", &fx("Security.evtx")])
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    {
        use std::io::{BufRead, BufReader};
        let mut r = BufReader::new(child.stdout.take().unwrap());
        let mut first = String::new();
        r.read_line(&mut first).unwrap();
        assert!(first.starts_with("{\"id\""));
    }
    let status = child.wait().unwrap();
    assert!(status.success(), "{status:?}");
}

