#[test]
fn fast_path_matches_json_path() {
    // The template-value fast path must produce exactly what the JSON path
    // produces (docs/PERF.md P-005); fixtures cover nested and flat payloads.
    let dir = fixtures().display().to_string();
    let fast = ok(&["parse", "-q", &dir]);
    let slow = ok(&["parse", "-q", "--slow-decoder", &dir]);
    assert_eq!(fast.lines().count(), slow.lines().count());
    for (a, b) in fast.lines().zip(slow.lines()) {
        assert_eq!(a, b);
    }
    let fast = ok(&["parse", "-q", "-F", "csv", &dir]);
    let slow = ok(&["parse", "-q", "-F", "csv", "--slow-decoder", &dir]);
    assert_eq!(fast, slow);
}

#[test]
fn checklist_sweep() {
    let checks = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../skill/references/checklists/checklists.json");
    let checks = checks.display().to_string();
    let out = ok(&[
        "checklist",
        "-q",
        "-k",
        &checks,
        &fx("Security.evtx"),
        &fx("System.evtx"),
        "-F",
        "json",
    ]);
    let v: Value = serde_json::from_str(&out).unwrap();
    let rows = v.as_array().unwrap();
    assert!(rows.len() > 200);
    let status = |id: &str| {
        rows.iter().find(|r| r["id"] == id).unwrap()["status"]
            .as_str()
            .unwrap()
            .to_string()
    };
    assert_eq!(status("FH-DEF-001"), "HIT?"); // 1102 in the scenario
    assert_eq!(status("FH-LAT-001"), "HIT?"); // PSEXESVC
    // No Sysmon file given: Sysmon checks must say the source is missing.
    assert_eq!(status("FH-CRED-001"), "LOG_SOURCE_MISSING");
    let md = ok(&[
        "checklist",
        "-q",
        "-k",
        &checks,
        &fx("Security.evtx"),
        "--tactic",
        "impact",
    ]);
    assert!(md.contains("## impact") && !md.contains("## execution"));
    // --actionable lists only HIT? / REVIEW rows, but the summary counts all.
    let act = ok(&[
        "checklist",
        "-q",
        "-k",
        &checks,
        &fx("Security.evtx"),
        "--actionable",
    ]);
    let rows_md: Vec<&str> = act.lines().filter(|l| l.starts_with("| FH-")).collect();
    assert!(!rows_md.is_empty() && act.contains("## Summary"));
    assert!(
        rows_md
            .iter()
            .all(|l| l.contains("| HIT? |") || l.contains("| REVIEW |"))
    );
    // Queries report their own coverage.
    let q = &rows.iter().find(|r| r["id"] == "FH-DEF-001").unwrap()["queries"][0];
    assert!(q["source_events"].as_u64().unwrap() > 0);
}

#[test]
fn llm_fields_projection_and_unique_keys() {
    let out = ok(&[
        "search",
        "-q",
        &fx("Security.evtx"),
        "-e",
        "4688",
        "--limit",
        "3",
    ]);
    for line in out.lines().filter(|l| l.starts_with("{\"id\"")) {
        let v: Value = serde_json::from_str(line).unwrap();
        let d = v["d"].as_object().unwrap();
        // 4688: the creator ProcessId is the parent (no repeated "pid").
        assert_eq!(
            line.matches("\"pid\":").count(),
            d.contains_key("pid") as usize
        );
    }
    let out = ok(&[
        "search",
        "-q",
        &fx("Security.evtx"),
        "-e",
        "4688",
        "--limit",
        "3",
        "--fields",
        "img,cmd",
    ]);
    for line in out.lines().filter(|l| l.starts_with("{\"id\"")) {
        let v: Value = serde_json::from_str(line).unwrap();
        assert!(
            v["d"]
                .as_object()
                .unwrap()
                .keys()
                .all(|k| k == "img" || k == "cmd")
        );
    }
}

#[test]
fn cyclic_string_table_does_not_hang() {
    // Header + first chunk of a fixture, with two string-table entries
    // pointing at each other (A -> B -> A).
    let data = std::fs::read(fx("Security.evtx")).unwrap();
    let mut d = data[..4096 + 65536].to_vec();
    let c = 4096;
    let heads: Vec<usize> = (0..64)
        .map(|i| u32::from_le_bytes(d[c + 128 + i * 4..c + 132 + i * 4].try_into().unwrap()))
        .filter(|&o| o != 0)
        .map(|o| o as usize)
        .collect();
    assert!(heads.len() >= 2);
    let (a, b) = (heads[0], heads[1]);
    d[c + a..c + a + 4].copy_from_slice(&(b as u32).to_le_bytes());
    d[c + b..c + b + 4].copy_from_slice(&(a as u32).to_le_bytes());
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("cycle.evtx");
    std::fs::write(&p, &d).unwrap();
    let mut child = Command::new(env!("CARGO_BIN_EXE_forhunt"))
        .args(["stats", "-q", "--slow-decoder", p.to_str().unwrap()])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    for _ in 0..200 {
        if let Some(st) = child.try_wait().unwrap() {
            assert!(st.success(), "{st:?}");
            return;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    child.kill().ok();
    panic!("forhunt hung on a cyclic string table");
}

#[test]
fn sampled_key_collision_keeps_both_files() {
    // corrupt.evtx has the same size and intact ends as Security.evtx, so the
    // sampled keys collide; it must still be parsed (and fail --strict).
    let (sec, bad) = (fx("Security.evtx"), fx("corrupt.evtx"));
    let o = forhunt(&["stats", "--strict", "-q", &sec, &bad]);
    assert_eq!(o.status.code(), Some(4));
    let out = ok(&["search", "-q", &sec, &bad, "-F", "jsonl"]);
    let v = lines(&out);
    let id = v
        .iter()
        .find(|e| {
            e["source_file"]
                .as_str()
                .unwrap_or("")
                .ends_with("corrupt.evtx")
        })
        .unwrap()["id"]
        .as_str()
        .unwrap()
        .to_string();
    assert!(!id.starts_with("4a2aa2ed"), "{id}");
    // Resolvable with or without the colliding file among the inputs.
    for p in [&bad, &fixtures().display().to_string()] {
        let s = lines(&ok(&["show", &id, "-p", p, "-F", "llm"]));
        assert_eq!(s[0]["id"], id.as_str());
    }
}

fn nfx(name: &str) -> String {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/ntfs")
        .join(name)
        .display()
        .to_string()
}

#[test]
fn ntfs_scenario() {
    let vol = nfx("WS-07");
    // Timestomped binary: $SI created before $FN created, zero sub-seconds.
    let v = lines(&ok(&[
        "search",
        "-q",
        &vol,
        "-c",
        "MFT",
        "-e",
        "16",
        "-f",
        "SiLtFn=true",
    ]));
    assert_eq!(summary(&v)["matches"], 2);
    assert_eq!(v[0]["d"]["path"], ".\\Windows\\PSEXESVC.exe");
    assert_eq!(v[0]["t"], "2019-03-19T14:23:11.000000Z");
    assert_eq!(v[0]["d"]["usec0"], true);
    // Download with its Zone.Identifier.
    let v = lines(&ok(&[
        "search",
        "-q",
        &vol,
        "-c",
        "MFT",
        "-f",
        "ZoneIdContents~198.51.100.7",
    ]));
    assert!(
        v[0]["d"]["path"]
            .as_str()
            .unwrap()
            .ends_with("\\Users\\Public\\u.ps1")
    );
    // Deleted dump: in $MFT (record not in use) and in $J, with resolved paths.
    let v = lines(&ok(&[
        "search",
        "-q",
        &vol,
        "-f",
        "Path~lsass.dmp",
        "-F",
        "jsonl",
    ]));
    assert!(
        v.iter()
            .any(|e| e["channel"] == "MFT" && e["data"]["Deleted"] == true)
    );
    let del: Vec<_> = v
        .iter()
        .filter(|e| e["channel"] == "UsnJrnl" && e["event_id"] == 2)
        .collect();
    assert_eq!(del.len(), 1);
    assert_eq!(del[0]["data"]["Path"], ".\\Users\\Public\\lsass.dmp");
    assert_eq!(del[0]["data"]["Reason"], "FileDelete|Close");
    // Rename old and new names.
    let v = lines(&ok(&[
        "search", "-q", &vol, "-c", "UsnJrnl", "-e", "3", "-F", "jsonl",
    ]));
    let names: Vec<_> = v
        .iter()
        .map(|e| e["data"]["FileName"].as_str().unwrap())
        .collect();
    assert_eq!(names, ["m.exe", "WinUpdate.exe", "WinUpdate.exe"]);
    // show: JSON and the native hex dump.
    let id = v[0]["id"].as_str().unwrap().to_string();
    let shown: Value = serde_json::from_str(&ok(&["show", "-q", &id, "-p", &vol])).unwrap();
    assert_eq!(shown["data"]["FileName"], "m.exe");
    let hex = ok(&["show", "-q", &id, "-p", &vol, "-F", "raw"]);
    assert!(hex.starts_with("00000000  "), "{hex}");
    // No host names in NTFS metadata: nothing in host facets.
    let st = lines(&ok(&["stats", "-q", &vol]));
    assert_eq!(st[0]["stats"]["hosts"], 0);
    assert!(!ok(&["stats", "-q", &vol]).contains("rid_gaps"));
}

#[test]
fn ntfs_timeline_merges_with_event_logs() {
    let out = ok(&[
        "timeline",
        "-q",
        &fx("System.evtx"),
        &nfx("WS-07"),
        "--since",
        "2024-03-11T10:21:00Z",
        "--until",
        "2024-03-11T10:23:00Z",
        "-F",
        "jsonl",
    ]);
    let v = lines(&out);
    let ts: Vec<_> = v
        .iter()
        .map(|e| e["timestamp"].as_str().unwrap().to_string())
        .collect();
    let mut sorted = ts.clone();
    sorted.sort();
    assert_eq!(ts, sorted);
    let ch: std::collections::BTreeSet<_> =
        v.iter().map(|e| e["channel"].as_str().unwrap()).collect();
    assert!(
        ch.contains("System") && ch.contains("MFT") && ch.contains("UsnJrnl"),
        "{ch:?}"
    );
}

#[test]
fn ntfs_damaged_inputs_and_determinism() {
    let o = forhunt(&["parse", "--strict", &nfx("corrupt.mft"), "-o", "-"]);
    assert_eq!(o.status.code(), Some(4));
    assert!(String::from_utf8_lossy(&o.stderr).contains("4 bad records"));
    ok(&["parse", "-q", &nfx("truncated.mft")]);
    let o = forhunt(&["parse", &nfx("corrupt_UsnJrnl.bin"), "-o", "-"]);
    assert!(o.status.success());
    assert!(String::from_utf8_lossy(&o.stderr).contains("1 bad records"));
    let a = ok(&["parse", "-q", "-t", "1", &nfx("")]);
    let b = ok(&["parse", "-q", "-t", "8", &nfx("")]);
    assert_eq!(a, b);
    // CSV rows use the same Timeline Explorer layout as event logs.
    let csv = ok(&[
        "search",
        "-q",
        &nfx("WS-07"),
        "-c",
        "MFT",
        "-f",
        "Path~PSEXESVC",
        "-F",
        "csv",
    ]);
    let row = csv.lines().nth(1).unwrap();
    assert!(
        row.contains(",MFT,") && row.contains("File timestamps ($SI)"),
        "{row}"
    );
}

#[test]
fn guid_filters_accept_the_windows_form() {
    // forhunt prints `A6B12C41-...`; Windows, Sysmon XML and SIEMs show
    // `{a6b12c41-...}`: a pivot pasted from them must find the same events.
    let first = lines(&ok(&[
        "search",
        &fx("Sysmon.evtx"),
        "-e",
        "1",
        "-n",
        "1",
        "-F",
        "jsonl",
        "-q",
    ]));
    let guid = first[0]["data"]["ProcessGuid"]
        .as_str()
        .unwrap()
        .to_string();
    let count = |f: &str| {
        let v = lines(&ok(&[
            "search",
            &fx("Sysmon.evtx"),
            "-f",
            f,
            "-n",
            "0",
            "-q",
        ]));
        summary(&v)["matches"].as_u64().unwrap()
    };
    let bare = count(&format!("ProcessGuid={guid}"));
    assert!(bare > 0);
    let windows = format!("{{{}}}", guid.to_lowercase());
    assert_eq!(count(&format!("ProcessGuid={windows}")), bare);
    assert_eq!(count(&format!("ProcessGuid~{windows}")), bare);
}

#[test]
fn checklist_service_queries_do_not_rely_on_translated_text() {
    // 7036 / 7040 state and start-type strings and service display names
    // are translated (French logs: "arrêté", "Désactivé", "Journal
    // d’événements Windows"): an English-only query is a silent NO_HIT.
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../skill/references/checklists/checklists.json");
    let v: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    for c in v["checks"].as_array().unwrap() {
        let qs: Vec<&str> = c["forhunt"]
            .as_array()
            .unwrap()
            .iter()
            .map(|q| q.as_str().unwrap())
            .collect();
        for q in &qs {
            let scm = q.contains("--event-id 7036") || q.contains("--event-id 7040");
            if !scm {
                continue;
            }
            assert!(
                !q.contains("param1="),
                "{}: display name match: {q}",
                c["id"]
            );
            if q.contains("--event-id 7036") && q.contains("param2=") {
                assert!(
                    qs.iter()
                        .any(|o| o.contains("--event-id 7036") && o.contains("Binary=")),
                    "{}: no language-independent 7036 state query besides {q}",
                    c["id"]
                );
            }
            assert!(
                !q.contains("param3=disabled") && !q.contains("param2=disabled"),
                "{}: English start type: {q}",
                c["id"]
            );
        }
    }
}

/// Splits a `narrow` suggestion (`--field 'A!=b$'`) into arguments.
fn split_flag(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut quoted = false;
    for c in s.chars() {
        match c {
            '\'' => quoted = !quoted,
            ' ' if !quoted => {
                if !cur.is_empty() {
                    out.push(std::mem::take(&mut cur));
                }
            }
            _ => cur.push(c),
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

#[test]
fn summary_counts_are_what_the_filters_return() {
    // top_values and narrow counts must be exactly what the analyst gets
    // by adding the filter: they decide what to look at next.
    let count = |base: &[&str], extra: &[String]| {
        let mut args = vec!["search", "-q", "-n", "0"];
        args.extend_from_slice(base);
        args.extend(extra.iter().map(String::as_str));
        let v = lines(&ok(&args));
        summary(&v)["matches"].as_u64().unwrap()
    };
    let sec = fx("Security.evtx");
    let all = fx("");
    for base in [
        vec![sec.as_str(), "-e", "4688"],
        vec![sec.as_str(), "-e", "4624"],
        vec![all.as_str(), "-e", "4624,4688,1"],
        vec![
            sec.as_str(),
            "-e",
            "4624",
            "--since",
            "2024-03-11T08:30:00Z",
        ],
        vec![all.as_str(), "--computer", "WS-07"],
    ] {
        let mut args = vec!["search", "-q", "-n", "1"];
        args.extend_from_slice(&base);
        let v = lines(&ok(&args));
        let s = summary(&v);
        for tv in s["top_values"].as_array().unwrap() {
            let (f, val, n) = (
                tv[0].as_str().unwrap(),
                tv[1].as_str().unwrap(),
                tv[2].as_u64().unwrap(),
            );
            assert_eq!(
                count(&base, &["-f".into(), format!("{f}={val}")]),
                n,
                "{base:?}: top value {f}={val}"
            );
        }
        for nw in s["narrow"].as_array().unwrap() {
            let add = nw["add"].as_str().unwrap();
            assert_eq!(
                count(&base, &split_flag(add)),
                nw["matches"].as_u64().unwrap(),
                "{base:?}: narrow {add}"
            );
        }
    }
}

#[test]
fn llm_fields_names_any_field_of_the_event() {
    // --fields must show a requested field even when the map does not
    // keep it by default: an empty `d` reads as "no such value".
    let jsonl = lines(&ok(&[
        "search",
        "-q",
        &fx("Security.evtx"),
        "-e",
        "4624",
        "-n",
        "1",
        "-F",
        "jsonl",
    ]));
    let data = jsonl[0]["data"].as_object().unwrap();
    let mut asked = Vec::new();
    for name in ["LogonGuid", "ProcessName", "KeyLength", "TargetUserName"] {
        if let Some(v) = data.get(name)
            && v.as_str() != Some("-")
            && v.as_str() != Some("")
        {
            asked.push(name);
        }
    }
    assert!(asked.len() >= 2, "{data:?}");
    let out = ok(&[
        "search",
        "-q",
        &fx("Security.evtx"),
        "-e",
        "4624",
        "-n",
        "1",
        "--fields",
        &asked.join(","),
    ]);
    let v: Value = serde_json::from_str(out.lines().next().unwrap()).unwrap();
    let d = v["d"].as_object().unwrap();
    assert_eq!(d.len(), asked.len(), "{asked:?} -> {d:?}");
}

#[test]
fn stats_record_gaps_inside_a_chunk_and_never_from_filters() {
    // Record removal as done by eventlogedit-style tools: the previous
    // record's size swallows the next one, inside the same chunk.
    let mut b = std::fs::read(fx("Security.evtx")).unwrap();
    let mut off = 4096 + 512;
    let mut recs = Vec::new();
    for _ in 0..6 {
        assert_eq!(&b[off..off + 4], b"**\0\0");
        let size = u32::from_le_bytes(b[off + 4..off + 8].try_into().unwrap()) as usize;
        let rid = u64::from_le_bytes(b[off + 8..off + 16].try_into().unwrap());
        recs.push((off, size, rid));
        off += size;
    }
    let ((a_off, a_size, a_rid), (_, b_size, b_rid)) = (recs[4], recs[5]);
    let new = (a_size + b_size) as u32;
    b[a_off + 4..a_off + 8].copy_from_slice(&new.to_le_bytes());
    let end = a_off + new as usize;
    b[end - 4..end].copy_from_slice(&new.to_le_bytes());
    let d = tempfile::tempdir().unwrap();
    let p = d.path().join("Security.evtx");
    std::fs::write(&p, &b).unwrap();
    let out = ok(&["stats", "-q", "-F", "json", &p.display().to_string()]);
    let v: Value = serde_json::from_str(&out).unwrap();
    let gaps = v["files"][0]["record_id_gaps"].as_array().unwrap();
    assert!(
        gaps.iter()
            .any(|g| g[0].as_u64() == Some(a_rid) && g[1].as_u64() == Some(b_rid + 1)),
        "removed record {b_rid} not reported: {gaps:?}"
    );
    // A filter keeps a subset of the records: the ids it skips are not gaps,
    // and its time spread says nothing about logging outages.
    let out = ok(&["stats", "-q", "-e", "4624", &fx("Security.evtx")]);
    assert!(!out.contains("rid_gaps"), "{out}");
    assert!(out.contains("\"quiet_periods\":[]"), "{out}");
}

#[test]
fn time_window_ignores_the_record_header_time() {
    // Forwarded or late-written events: the record header (write) time can
    // be days after TimeCreated. A --since/--until window on TimeCreated
    // must still find them, on both decoding paths.
    let mut b = std::fs::read(fx("Security.evtx")).unwrap();
    let off = 4096 + 512 + 1790; // second record of the first chunk
    assert_eq!(&b[off..off + 4], b"**\0\0");
    let rid = u64::from_le_bytes(b[off + 8..off + 16].try_into().unwrap());
    let ft = u64::from_le_bytes(b[off + 16..off + 24].try_into().unwrap());
    let late = ft + 3 * 86_400 * 10_000_000;
    b[off + 16..off + 24].copy_from_slice(&late.to_le_bytes());
    let d = tempfile::tempdir().unwrap();
    let p = d.path().join("Security.evtx");
    std::fs::write(&p, &b).unwrap();
    let p = p.display().to_string();
    let first = lines(&ok(&["parse", "-q", &p]));
    let ev = first
        .iter()
        .find(|e| e["record_id"].as_u64() == Some(rid))
        .unwrap();
    let t = ev["timestamp"].as_str().unwrap().to_string();
    for extra in [&[][..], &["--slow-decoder"][..]] {
        for cmd in ["search", "timeline"] {
            let mut args = vec![cmd, "-q", "-n", "0", &p, "--since", &t, "--until", &t];
            args.extend_from_slice(extra);
            let v = lines(&ok(&args));
            assert_eq!(
                summary(&v)["matches"].as_u64(),
                Some(1),
                "{cmd} {extra:?} missed record {rid} at {t}"
            );
        }
    }
}

/// A copy of a fixture with every record header id lowered by `by`, as in
/// exported logs (headers renumbered, System/EventRecordID kept).
fn renumbered(name: &str, by: u64) -> (tempfile::TempDir, String) {
    let mut b = std::fs::read(fx(name)).unwrap();
    let rd = |b: &[u8], o: usize| u64::from_le_bytes(b[o..o + 8].try_into().unwrap());
    let mut c = 4096;
    while c + 65536 <= b.len() {
        if &b[c..c + 8] == b"ElfChnk\0" {
            for f in [24, 32] {
                let v = rd(&b, c + f) - by;
                b[c + f..c + f + 8].copy_from_slice(&v.to_le_bytes());
            }
            let free = u32::from_le_bytes(b[c + 48..c + 52].try_into().unwrap()) as usize;
            let mut o = c + 512;
            while o + 24 <= c + free && &b[o..o + 4] == b"**\0\0" {
                let size = u32::from_le_bytes(b[o + 4..o + 8].try_into().unwrap()) as usize;
                let v = rd(&b, o + 8) - by;
                b[o + 8..o + 16].copy_from_slice(&v.to_le_bytes());
                o += size;
            }
        }
        c += 65536;
    }
    let d = tempfile::tempdir().unwrap();
    let p = d.path().join(name);
    std::fs::write(&p, &b).unwrap();
    let p = p.display().to_string();
    (d, p)
}

#[test]
fn show_warns_when_header_id_and_event_record_id_differ() {
    let (_d, p) = renumbered("System.evtx", 8000);
    let v = lines(&ok(&["parse", "-q", &p]));
    let e = &v[3];
    let (id, header, erid) = (
        e["id"].as_str().unwrap().to_string(),
        e["record_id"].as_u64().unwrap(),
        e["event_record_id"].as_u64().unwrap(),
    );
    assert_ne!(header, erid);
    let key = id.split(':').next().unwrap();
    for fmt in ["json", "llm", "xml"] {
        // By header id: shown, with a warning naming the EventRecordID.
        let o = forhunt(&["show", &id, "-p", &p, "-F", fmt]);
        assert!(o.status.success(), "{fmt}");
        let err = String::from_utf8_lossy(&o.stderr);
        assert!(
            err.contains("warning") && err.contains(&erid.to_string()),
            "{fmt}: {err}"
        );
    }
    // By EventRecordID (Hayabusa's RecordID): shown, with a warning naming
    // the forhunt id of that record.
    for fmt in ["json", "xml"] {
        let o = forhunt(&["show", &format!("{key}:{erid}"), "-p", &p, "-F", fmt]);
        assert!(o.status.success(), "{fmt}");
        let err = String::from_utf8_lossy(&o.stderr);
        assert!(err.contains("warning") && err.contains(&id), "{fmt}: {err}");
    }
}

#[test]
fn overlapping_copies_of_one_log_are_reported() {
    // A truncated copy of Security.evtx is another collection of the same
    // log: its events would be counted twice.
    let o = forhunt(&["stats", &fx("Security.evtx"), &fx("truncated.evtx")]);
    assert!(o.status.success());
    let err = String::from_utf8_lossy(&o.stderr);
    assert!(
        err.lines().any(|l| l.contains("warning")
            && l.contains("overlapping")
            && l.contains("Security.evtx")
            && l.contains("truncated.evtx")),
        "{err}"
    );
    // Different logs: nothing to report.
    let o = forhunt(&["stats", &fx("Security.evtx"), &fx("Sysmon.evtx")]);
    assert!(!String::from_utf8_lossy(&o.stderr).contains("overlapping"));
}
